    # Commits are likely in article or listitem elements; use get_by_role to find them
    email_counts = {}
    # Try to find all commit elements; common roles might be 'article' or 'listitem'
    commit_elements = page.get_by_role("article")  # Adjust role if needed based on actual page structure
    count = await commit_elements.count()
