    # If no emails found with 'article', try other roles like 'listitem' or 'link'
    if not email_counts:
        all_elements = page.get_by_role("link")  # Emails might be in links
        count_all = await all_elements.count()
        for i in range(count_all):
            element = all_elements.nth(i)
